//! The graph's RECORD STORE, as a database (`epic-retire-json-ledgers-for-db-and-git-drivers`).
//!
//! Replaces the 27.5 MB committed JSON ledger, the 50 MB runtime blob, the packaged seed and the
//! propagation between them — "a record edit is four writes", and the copy the app reads was the one
//! nothing updated.
//!
//! # History is the SHAPE, not a hook
//!
//! There is no "current record" row. [`RECORD_REVS`] is append-only and holds every version ever
//! written; `records` is a VIEW selecting each id's highest rev. A write is an INSERT, so there is
//! nothing to overwrite and no way to lose a version by writing one.
//!
//! THE ALTERNATIVE WAS A TRIGGER, and it was rejected on evidence. A trigger that mirrors each write
//! into a history table is real enforcement right up until someone runs `DROP TRIGGER` — measured on
//! SQLite 3.46: after dropping it, writes continued, `current` advanced to rev 4, history stopped at
//! rev 3, and nothing anywhere raised. A store whose guarantee can be silently switched off by one
//! statement is not a store that can be used to self-heal. Here, dropping every trigger in the schema
//! changes nothing, because there are none to drop.
//!
//! What the primary key `(id, rev)` adds is that a version cannot be REWRITTEN either: replaying an
//! existing rev is a constraint violation, not a silent clobber.
//!
//! # Reverting is going FORWARD
//!
//! [`revert`] does not undo. It reads the content at an older rev and appends it as a NEW one, so the
//! act of reverting is itself a version and the history is never rewritten. That is what makes "move
//! back a version, then handle the error when we can" recoverable in both directions.
//!
//! # Why the projected columns exist
//!
//! `name`/`role`/`tech`/`folder`/`provides`/`src` are `GENERATED ALWAYS … STORED` from the record
//! body, so the queries the app makes never parse a body they are not going to show. They cannot
//! drift from the record, because SQLite computes them from it. MEASURED over the real store (1,403
//! records, 3,715 revisions): the whole-index read is 8.9 ms against 26.6 ms parsing bodies, and the
//! resolver's read 13.6 ms against 51.6 ms, for 1 MB more on disk.

/// The store's default location, or `$BSC_GRAPH_DB`.
pub fn default_path() -> Option<std::path::PathBuf> {
    bsc_sqlite_util::default_store_path("BSC_GRAPH_DB", &["knowledge", "graph.db"])
}

pub use rusqlite::Connection;
use rusqlite::params;
use serde_json::Value;
use std::path::Path;

/// The append-only ledger. Every version of every record, including tombstones.
pub const RECORD_REVS: &str = "record_revs";

/// The schema, applied on every open. Idempotent.
///
/// `records` is a VIEW and is deliberately not a table: a table would be a second copy of the truth,
/// and keeping two copies in step is the entire class of bug this store exists to remove.
pub const SCHEMA: &str = r#"
CREATE TABLE IF NOT EXISTS record_revs (
  id       TEXT    NOT NULL,
  -- WHICH LANE this version belongs to. `main` is the landed history; a work item writes its own lane
  -- and reads lane-over-main, so an in-progress record is invisible to every other session until it
  -- lands. Git branches never gave records this: every worktree shared one runtime store, which is
  -- what the 304 drifted records were.
  lane     TEXT    NOT NULL DEFAULT 'main',
  rev      INTEGER NOT NULL CHECK (rev > 0),
  -- The `main` rev this lane branched from, on a lane's FIRST write to a record. `NULL` on main
  -- itself. It is what makes a conflict decidable rather than guessed: if main has moved past it by
  -- the time the lane lands, the two sides changed the same record from the same base, and base/ours/
  -- theirs are all three still in the ledger.
  base_rev INTEGER,
  -- The record body. NULL is a TOMBSTONE — the record was removed at this rev, which is itself a
  -- version you can come back from, rather than an absence you cannot distinguish from never-existed.
  json     TEXT,
  -- 'impl' or 'edge'. An EDGE is a record of a different TIER, not of a different store: it has an id,
  -- a body and a history exactly as an implementation does, and giving it its own table would mean two
  -- places to remember when adding a version.
  tier     TEXT    NOT NULL DEFAULT 'impl',
  at       INTEGER NOT NULL,
  by       TEXT    NOT NULL DEFAULT '',
  note     TEXT,
  -- Projected from the body by SQLite, so they cannot drift from it and a listing never parses a body.
  name     TEXT GENERATED ALWAYS AS (json_extract(json, '$.name'))     STORED,
  role     TEXT GENERATED ALWAYS AS (json_extract(json, '$.role'))     STORED,
  tech     TEXT GENERATED ALWAYS AS (json_extract(json, '$.tech'))     STORED,
  folder   TEXT GENERATED ALWAYS AS (json_extract(json, '$.folder'))   STORED,
  src      TEXT GENERATED ALWAYS AS (json_extract(json, '$.src'))      STORED,
  provides TEXT GENERATED ALWAYS AS (json_extract(json, '$.provides')) STORED,
  PRIMARY KEY (id, lane, rev)
);
CREATE INDEX IF NOT EXISTS record_revs_head     ON record_revs(id, lane, rev DESC);
CREATE INDEX IF NOT EXISTS record_revs_lane     ON record_revs(lane);
CREATE INDEX IF NOT EXISTS record_revs_provides ON record_revs(provides);
CREATE INDEX IF NOT EXISTS record_revs_folder   ON record_revs(folder);

-- `records` is the LANDED graph — lane `main`. Everything that reads "the store" without naming a
-- lane (the app, the build export, every existing caller) gets this, so an unlanded record cannot leak
-- into a build or onto the page.
CREATE VIEW IF NOT EXISTS records AS
  SELECT id, json, rev, tier, at, by, name, role, tech, folder, src, provides
    FROM record_revs r
   WHERE lane = 'main'
     AND rev = (SELECT MAX(rev) FROM record_revs WHERE id = r.id AND lane = 'main')
     AND json IS NOT NULL;
"#;

/// Open (creating if needed) the store at `path` and apply [`SCHEMA`].
pub fn open(path: &Path) -> Result<Connection, String> {
    let conn = bsc_sqlite_util::open_db_str(path, "graph store")?;
    conn.execute_batch(SCHEMA).map_err(|e| format!("graph store schema: {e}"))?;
    Ok(conn)
}

/// The lane every landed record lives in. Reads that do not name a lane get this.
pub const MAIN: &str = "main";

/// The IMPLEMENTATION tier — a node that IS its source.
pub const TIER_IMPL: &str = "impl";
/// The RELATIONSHIP tier — a test spanning two records is evidence about the EDGE, not about either.
pub const TIER_EDGE: &str = "edge";

/// The highest rev recorded for `id` IN `lane`, including a tombstone. `0` when the lane has never
/// written it — which is how a read knows to fall through to main.
pub fn head_rev_in(conn: &Connection, lane: &str, id: &str) -> Result<i64, String> {
    conn.query_row(
        "SELECT COALESCE(MAX(rev), 0) FROM record_revs WHERE id = ?1 AND lane = ?2",
        params![id, lane],
        |r| r.get(0),
    )
    .map_err(|e| format!("head rev for '{id}' in lane '{lane}': {e}"))
}

/// [`head_rev_in`] on `main`.
pub fn head_rev(conn: &Connection, id: &str) -> Result<i64, String> {
    head_rev_in(conn, MAIN, id)
}

/// One record's CURRENT body as `lane` sees it — the lane's own version if it has one, else main's.
///
/// LANE-OVER-MAIN is the whole isolation model: a lane holds rows only for records it has written, so
/// a lane that touched four records is four rows against 2,529 and every other record still reads
/// through to the landed graph.
pub fn get_in(conn: &Connection, lane: &str, id: &str) -> Result<Option<Value>, String> {
    let from = |l: &str| -> Option<Option<String>> {
        conn.query_row(
            "SELECT json FROM record_revs r WHERE id = ?1 AND lane = ?2
              AND rev = (SELECT MAX(rev) FROM record_revs WHERE id = ?1 AND lane = ?2)",
            params![id, l],
            |r| r.get::<_, Option<String>>(0),
        )
        .ok()
    };
    // `Some(None)` is a TOMBSTONE and is an ANSWER — a lane that removed a record must not fall
    // through to main and resurrect it.
    let row = match from(lane) {
        Some(v) => v,
        None if lane != MAIN => match from(MAIN) {
            Some(v) => v,
            None => return Ok(None),
        },
        None => return Ok(None),
    };
    match row {
        None => Ok(None),
        Some(s) => serde_json::from_str(&s).map(Some).map_err(|e| format!("record '{id}' is not valid JSON: {e}")),
    }
}

/// [`get_in`] on `main`.
pub fn get(conn: &Connection, id: &str) -> Result<Option<Value>, String> {
    get_in(conn, MAIN, id)
}

/// The main rev this lane is basing `id` on — its own recorded base, or main's head if it has not
/// written the record yet.
///
/// CARRIED FORWARD on every lane write rather than set once. It has to be: `rebase_record` moves the
/// base, and a later edit that reset it to the first write's value would make the record conflict
/// again for a reason already resolved.
fn lane_base(conn: &Connection, lane: &str, id: &str) -> Result<i64, String> {
    let existing: Option<i64> = conn
        .query_row(
            "SELECT base_rev FROM record_revs r WHERE id = ?1 AND lane = ?2
              AND rev = (SELECT MAX(rev) FROM record_revs WHERE id = ?1 AND lane = ?2)",
            params![id, lane],
            |r| r.get(0),
        )
        .ok()
        .flatten();
    match existing {
        Some(b) => Ok(b),
        None => head_rev(conn, id),
    }
}

/// Append a new version of `id` on `main`.
///
/// `expect_rev` is OPTIMISTIC CONCURRENCY — `Some(n)` refuses the write unless the current head is
/// exactly `n`. Either way the new rev is head + 1 and the old one is still on disk.
pub fn put(
    conn: &Connection,
    id: &str,
    body: &Value,
    by: &str,
    note: Option<&str>,
    expect_rev: Option<i64>,
) -> Result<i64, String> {
    put_in(conn, MAIN, id, body, Write::by(by).note(note).expecting(expect_rev))
}

/// [`put`] into a named lane, as an implementation.
pub fn put_lane(
    conn: &Connection,
    lane: &str,
    id: &str,
    body: &Value,
    by: &str,
    note: Option<&str>,
) -> Result<i64, String> {
    put_in(conn, lane, id, body, Write::by(by).note(note))
}

/// Everything a write carries besides the record itself — who, why, what it expected, which tier.
///
/// A struct rather than four more parameters: `put_in` reached eight arguments and every call site had
/// to remember an order in which two of them were `Option`s and two were `&str`. Naming them at the
/// call site is the difference between a write you can read and one you check against the signature.
#[derive(Debug, Clone, Copy)]
pub struct Write<'a> {
    /// Who is writing — stamped on the version.
    pub by: &'a str,
    /// Why, if there is a reason worth keeping.
    pub note: Option<&'a str>,
    /// OPTIMISTIC CONCURRENCY: refuse unless the head is exactly this.
    pub expect_rev: Option<i64>,
    /// [`TIER_IMPL`] or [`TIER_EDGE`].
    pub tier: &'a str,
}

impl<'a> Write<'a> {
    /// An ordinary implementation write by `by`.
    pub fn by(by: &'a str) -> Self {
        Self { by, note: None, expect_rev: None, tier: TIER_IMPL }
    }
    /// …with a reason.
    pub fn note(mut self, note: Option<&'a str>) -> Self {
        self.note = note;
        self
    }
    /// …refusing a stale write.
    pub fn expecting(mut self, rev: Option<i64>) -> Self {
        self.expect_rev = rev;
        self
    }
    /// …on the relationship tier.
    pub fn tier(mut self, tier: &'a str) -> Self {
        self.tier = tier;
        self
    }
}

/// The write, naming both the lane and the tier.
pub fn put_in(conn: &Connection, lane: &str, id: &str, body: &Value, w: Write<'_>) -> Result<i64, String> {
    let head = head_rev_in(conn, lane, id)?;
    if let Some(want) = w.expect_rev {
        if head != want {
            return Err(format!(
                "'{id}' is at rev {head} in lane '{lane}', not {want} — someone else wrote it since \
                 you read it. Re-read and reapply; nothing was changed."
            ));
        }
    }
    let next = head + 1;
    // THE BASE, on a lane's FIRST write to a record: which main rev it branched from. That single
    // number is what turns "did someone else touch this too" from a guess into a comparison.
    let base = if lane != MAIN { Some(lane_base(conn, lane, id)?) } else { None };
    let text = serde_json::to_string(body).map_err(|e| format!("cannot serialize '{id}': {e}"))?;
    conn.execute(
        "INSERT INTO record_revs (id, lane, rev, base_rev, json, tier, at, by, note)
         VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, ?9)",
        params![id, lane, next, base, text, w.tier, now_ms(), w.by, w.note],
    )
    .map_err(|e| format!("cannot write '{id}' rev {next} in lane '{lane}': {e}"))?;
    Ok(next)
}

/// Remove `id` on `main` by appending a TOMBSTONE — a version with no body.
///
/// Not a DELETE: the record stops being current while every version of it stays readable, so a removal
/// is as recoverable as any other write.
pub fn remove(conn: &Connection, id: &str, by: &str, note: Option<&str>) -> Result<i64, String> {
    remove_in(conn, MAIN, id, by, note)
}

/// [`remove`] in a named lane.
pub fn remove_in(conn: &Connection, lane: &str, id: &str, by: &str, note: Option<&str>) -> Result<i64, String> {
    if get_in(conn, lane, id)?.is_none() {
        return Err(format!("no record '{id}' in lane '{lane}' — nothing to remove"));
    }
    let head = head_rev_in(conn, lane, id)?;
    let base = if lane != MAIN { Some(lane_base(conn, lane, id)?) } else { None };
    let next = head + 1;
    conn.execute(
        "INSERT INTO record_revs (id, lane, rev, base_rev, json, at, by, note)
         VALUES (?1, ?2, ?3, ?4, NULL, ?5, ?6, ?7)",
        params![id, lane, next, base, now_ms(), by, note],
    )
    .map_err(|e| format!("cannot tombstone '{id}' in lane '{lane}': {e}"))?;
    Ok(next)
}

/// Restore the content `id` had at `rev` on main, as a NEW version.
///
/// THE SELF-HEAL PATH. It goes forward, never back: history is never rewritten, so a revert can itself
/// be reverted and the record of what went wrong survives the recovery from it.
pub fn revert(conn: &Connection, id: &str, rev: i64, by: &str) -> Result<i64, String> {
    let body: Option<String> = conn
        .query_row(
            "SELECT json FROM record_revs WHERE id = ?1 AND lane = 'main' AND rev = ?2",
            params![id, rev],
            |r| r.get(0),
        )
        .map_err(|_| format!("'{id}' has no rev {rev} — reachable revs: {:?}", revs(conn, id).unwrap_or_default()))?;
    match body {
        None => remove(conn, id, by, Some(&format!("revert to rev {rev} (a tombstone)"))),
        Some(text) => {
            let v: Value = serde_json::from_str(&text).map_err(|e| format!("rev {rev} of '{id}' is not valid JSON: {e}"))?;
            put(conn, id, &v, by, Some(&format!("revert to rev {rev}")), None)
        }
    }
}

/// Every rev recorded for `id`, newest first.
pub fn revs(conn: &Connection, id: &str) -> Result<Vec<i64>, String> {
    let mut st = conn
        .prepare("SELECT rev FROM record_revs WHERE id = ?1 AND lane = 'main' ORDER BY rev DESC")
        .map_err(|e| e.to_string())?;
    let rows = st.query_map([id], |r| r.get::<_, i64>(0)).map_err(|e| e.to_string())?;
    rows.collect::<Result<Vec<_>, _>>().map_err(|e| e.to_string())
}

/// Milliseconds since the epoch — the stamp every version carries.
fn now_ms() -> i64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_millis() as i64)
        .unwrap_or(0)
}

/// How many records are CURRENT — one row per live id.
pub fn count(conn: &Connection) -> Result<i64, String> {
    conn.query_row("SELECT COUNT(*) FROM records", [], |r| r.get(0)).map_err(|e| e.to_string())
}

/// How many versions the ledger holds, across every record.
pub fn rev_count(conn: &Connection) -> Result<i64, String> {
    conn.query_row("SELECT COUNT(*) FROM record_revs", [], |r| r.get(0)).map_err(|e| e.to_string())
}

/// The whole graph document AS `lane` SEES IT — its own records over main's.
///
/// What a worktree bound to a lane must EXPORT for its build: the lane's version of everything it has
/// touched, and main's for everything else.
pub fn document_in(conn: &Connection, lane: &str) -> Result<Value, String> {
    if lane == MAIN {
        return document(conn);
    }
    let tier = |t: &str| -> Result<Vec<Value>, String> {
        // Lane-over-main in one statement. A lane TOMBSTONE is respected — `json IS NOT NULL` drops it
        // from both arms, so a record the lane removed does not reappear from main and the build does
        // not compile a module its author deleted.
        let mut st = conn
            .prepare(
                "SELECT json FROM record_revs r
                  WHERE r.lane = ?1 AND r.tier = ?2 AND r.json IS NOT NULL
                    AND r.rev = (SELECT MAX(rev) FROM record_revs WHERE id = r.id AND lane = ?1)
                  UNION ALL
                 SELECT json FROM record_revs m
                  WHERE m.lane = 'main' AND m.tier = ?2 AND m.json IS NOT NULL
                    AND m.rev = (SELECT MAX(rev) FROM record_revs WHERE id = m.id AND lane = 'main')
                    AND NOT EXISTS (SELECT 1 FROM record_revs WHERE id = m.id AND lane = ?1)",
            )
            .map_err(|e| e.to_string())?;
        let rows = st.query_map(params![lane, t], |r| r.get::<_, String>(0)).map_err(|e| e.to_string())?;
        rows.map(|r| r.map_err(|e| e.to_string()).and_then(|s| serde_json::from_str(&s).map_err(|e| e.to_string())))
            .collect()
    };
    Ok(serde_json::json!({
        "version": 1,
        "implementations": tier(TIER_IMPL)?,
        "edges": tier(TIER_EDGE)?,
    }))
}

/// The whole graph document, rebuilt from the ledger — the shape every existing reader expects.
///
/// `{ implementations: [...], edges: [...] }`, each from the head of its tier. This is what lets the
/// database replace the JSON ledger without every caller changing at once: `bsc_graph::load` returns
/// this, and nothing downstream can tell where it came from.
pub fn document(conn: &Connection) -> Result<Value, String> {
    let tier = |t: &str| -> Result<Vec<Value>, String> {
        let mut st = conn
            .prepare("SELECT json FROM records WHERE tier = ?1 ORDER BY id")
            .map_err(|e| e.to_string())?;
        let rows = st.query_map([t], |r| r.get::<_, String>(0)).map_err(|e| e.to_string())?;
        rows.map(|r| {
            r.map_err(|e| e.to_string())
                .and_then(|s| serde_json::from_str(&s).map_err(|e| e.to_string()))
        })
        .collect()
    };
    Ok(serde_json::json!({
        "version": 1,
        "implementations": tier(TIER_IMPL)?,
        "edges": tier(TIER_EDGE)?,
    }))
}

/// What one [`sync_document`] did.
#[derive(Debug, Default, PartialEq, Eq, serde::Serialize)]
pub struct Sync {
    pub added: usize,
    pub changed: usize,
    pub removed: usize,
    pub unchanged: usize,
}

/// Write a whole document into the ledger, as the DELTA against what is already there.
///
/// # A save must not be a new version of everything
///
/// Every existing `bsc graph` write path mutates the whole document and calls `save`. Appending a
/// version per record on each of those would put 2,529 revisions in the ledger for a one-record edit,
/// and the history would be worthless within a day — every rev would say "something, somewhere,
/// changed". So this compares each record against the current head and writes only what actually
/// moved: one `impl set` becomes one revision, which is the property that makes `revert` mean
/// something.
///
/// A record the document no longer carries is TOMBSTONED rather than deleted, so a removal stays as
/// recoverable as any other write.
pub fn sync_document(conn: &Connection, doc: &Value, by: &str, note: Option<&str>) -> Result<Sync, String> {
    let mut out = Sync::default();
    let mut seen: std::collections::BTreeSet<String> = Default::default();
    for (key, tier) in [("implementations", TIER_IMPL), ("edges", TIER_EDGE)] {
        for rec in doc.get(key).and_then(Value::as_array).map(Vec::as_slice).unwrap_or(&[]) {
            let Some(id) = rec.get("id").and_then(Value::as_str) else { continue };
            seen.insert(id.to_string());
            let body = import::body_of(rec);
            match get(conn, id)? {
                Some(cur) if same_body(&cur, &body) => out.unchanged += 1,
                Some(_) => {
                    put_in(conn, MAIN, id, &body, Write::by(by).note(note).tier(tier))?;
                    out.changed += 1;
                }
                None => {
                    put_in(conn, MAIN, id, &body, Write::by(by).note(note).tier(tier))?;
                    out.added += 1;
                }
            }
        }
    }
    let mut st = conn.prepare("SELECT id FROM records").map_err(|e| e.to_string())?;
    let live: Vec<String> = st
        .query_map([], |r| r.get::<_, String>(0))
        .map_err(|e| e.to_string())?
        .collect::<Result<_, _>>()
        .map_err(|e| e.to_string())?;
    for id in live {
        if !seen.contains(&id) {
            remove(conn, &id, by, note)?;
            out.removed += 1;
        }
    }
    Ok(out)
}

// ── THE APP'S QUERIES ────────────────────────────────────────────────────────────────────────────
//
// What the Algorithms page and the module resolver each need, as SELECTs rather than as projections
// over a whole document. This is the half of the migration the app actually feels: `graph_dump` used
// to hand the webview 50.76 MB every five seconds because a JSON blob has no way to answer "just the
// fields I render" — a database does.

/// The page's INDEX — every current record, page fields only, no bodies.
///
/// Straight off the STORED generated columns, so no body is parsed for a record the page is only going
/// to list. MEASURED over 2,529 records: 8.9 ms against 26.6 ms parsing bodies.
pub fn index(conn: &Connection) -> Result<Vec<Value>, String> {
    let mut st = conn
        .prepare(
            "SELECT id, name, role, tech, folder, src, provides, rev,
                    json_extract(json, '$.summary'), json_extract(json, '$.composes'),
                    json_extract(json, '$.kind'), json_extract(json, '$.tags'),
                    json_extract(json, '$.ref'), json_extract(json, '$.domain'),
                    json_extract(json, '$.feature')
               FROM records WHERE tier = 'impl' ORDER BY id",
        )
        .map_err(|e| e.to_string())?;
    let rows = st
        .query_map([], |r| {
            let arr = |s: Option<String>| -> Value {
                s.and_then(|s| serde_json::from_str(&s).ok()).unwrap_or(Value::Array(vec![]))
            };
            Ok(serde_json::json!({
                "id": r.get::<_, String>(0)?,
                "name": r.get::<_, Option<String>>(1)?,
                "role": r.get::<_, Option<String>>(2)?,
                "tech": r.get::<_, Option<String>>(3)?,
                "folder": r.get::<_, Option<String>>(4)?,
                "src": r.get::<_, Option<String>>(5)?,
                "provides": r.get::<_, Option<String>>(6)?,
                "rev": r.get::<_, i64>(7)?,
                "summary": r.get::<_, Option<String>>(8)?,
                "composes": arr(r.get::<_, Option<String>>(9)?),
                "kind": r.get::<_, Option<String>>(10)?,
                "tags": arr(r.get::<_, Option<String>>(11)?),
                "ref": r.get::<_, Option<String>>(12)?,
                "domain": r.get::<_, Option<String>>(13)?,
                "feature": r.get::<_, Option<String>>(14)?,
            }))
        })
        .map_err(|e| e.to_string())?;
    rows.collect::<Result<Vec<_>, _>>().map_err(|e| e.to_string())
}

/// The RESOLVER's feed — every record that provides a specifier, with its source.
///
/// Indexed on `provides`, so this touches only the 665 records that can ever match rather than all
/// 2,529. It is a different question from [`index`] and always was: the page renders records, the
/// resolver turns an `@/…` import into source. Serving both from one read is what took the app down.
pub fn modules(conn: &Connection) -> Result<Vec<Value>, String> {
    let mut st = conn
        .prepare(
            "SELECT id, provides, json_extract(json, '$.code')
               FROM records WHERE tier = 'impl' AND provides IS NOT NULL AND provides <> '' ORDER BY id",
        )
        .map_err(|e| e.to_string())?;
    let rows = st
        .query_map([], |r| {
            Ok(serde_json::json!({
                "id": r.get::<_, String>(0)?,
                "provides": r.get::<_, String>(1)?,
                "code": r.get::<_, Option<String>>(2)?,
            }))
        })
        .map_err(|e| e.to_string())?;
    rows.collect::<Result<Vec<_>, _>>().map_err(|e| e.to_string())
}

/// ONE record's source, by id — what the inspector shows for the record on screen.
pub fn source(conn: &Connection, id: &str) -> Result<Option<Value>, String> {
    conn.query_row(
        "SELECT json_extract(json, '$.code'), json_extract(json, '$.vizCode') FROM records WHERE id = ?1",
        [id],
        |r| {
            Ok(serde_json::json!({
                "id": id,
                "code": r.get::<_, Option<String>>(0)?,
                "vizCode": r.get::<_, Option<String>>(1)?,
            }))
        },
    )
    .map(Some)
    .or(Ok(None))
}

/// A content signature over the ledger's HEADS — what changes when any record does.
///
/// Over `(id, rev)` rather than over bodies, and that is the whole point: a rev moves if and only if a
/// record was written, so this answers "has anything changed" without reading a single body. The
/// signature the app polls used to require serialising the entire projected document first.
pub fn signature(conn: &Connection) -> Result<String, String> {
    let mut st = conn
        .prepare("SELECT id, rev FROM records ORDER BY id")
        .map_err(|e| e.to_string())?;
    let rows = st
        .query_map([], |r| Ok(format!("{}:{}", r.get::<_, String>(0)?, r.get::<_, i64>(1)?)))
        .map_err(|e| e.to_string())?;
    let joined = rows.collect::<Result<Vec<_>, _>>().map_err(|e| e.to_string())?.join("\u{1e}");
    Ok(bsc_cli_util::vendored::sha256_hex(joined.as_bytes()))
}

/// Whether two bodies say the same thing, ignoring key order.
///
/// `preserve_order` is on in this workspace, so `==` on `Value` reports a difference for records that
/// merely round-tripped through a map with a different insertion order — which would make every save a
/// new version of everything, the exact thing [`sync_document`] exists to avoid.
pub(crate) fn same_body(a: &Value, b: &Value) -> bool {
    fn canon(v: &Value) -> String {
        match v {
            Value::Object(m) => {
                let mut keys: Vec<&String> = m.keys().collect();
                keys.sort();
                format!(
                    "{{{}}}",
                    keys.iter().map(|k| format!("{k}:{}", canon(&m[*k]))).collect::<Vec<_>>().join(",")
                )
            }
            Value::Array(a) => format!("[{}]", a.iter().map(canon).collect::<Vec<_>>().join(",")),
            other => other.to_string(),
        }
    }
    canon(a) == canon(b)
}

// ── LANES ────────────────────────────────────────────────────────────────────────────────────────
//
// A lane is what a git branch was for files, for records. It is COPY-ON-WRITE: it holds rows only for
// the records it has written, and everything else reads through to `main`. Measured over this repo's
// last 40 merges, a slice touches a MEDIAN OF 4 RECORDS — so a lane is four rows against 2,529, and
// "would a branch duplicate the store" is answered by never copying what you did not touch.
//
// A lane is not a second store. It lives in the same ledger, under the same append-only rules, with
// the same history — so nothing about opening one weakens the guarantee that a version is somewhere
// you can go back to.

/// One record a lane has changed, against what `main` says now.
#[derive(Debug, PartialEq, Eq, serde::Serialize)]
pub struct LaneChange {
    pub id: String,
    /// The main rev the lane branched from.
    pub base_rev: i64,
    /// What main is at NOW. Ahead of `base_rev` means both sides moved the same record.
    pub main_rev: i64,
    /// The lane's own head.
    pub lane_rev: i64,
    /// `true` when the lane tombstoned the record.
    pub removed: bool,
    /// `true` when main moved past the base — this record cannot land without a decision.
    pub conflicted: bool,
}

/// Every record `lane` has touched, with the state that decides whether it can land.
pub fn lane_changes(conn: &Connection, lane: &str) -> Result<Vec<LaneChange>, String> {
    if lane == MAIN {
        return Err("`main` is the landed graph, not a lane — nothing to compare it against".into());
    }
    let mut st = conn
        .prepare(
            "SELECT r.id, r.rev, COALESCE(r.base_rev, 0)
               FROM record_revs r
              WHERE r.lane = ?1
                AND r.rev = (SELECT MAX(rev) FROM record_revs WHERE id = r.id AND lane = ?1)
              ORDER BY r.id",
        )
        .map_err(|e| e.to_string())?;
    let rows: Vec<(String, i64, i64)> = st
        .query_map([lane], |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)))
        .map_err(|e| e.to_string())?
        .collect::<Result<_, _>>()
        .map_err(|e| e.to_string())?;
    let mut out = Vec::new();
    for (id, lane_rev, base_rev) in rows {
        let main_rev = head_rev(conn, &id)?;
        out.push(LaneChange {
            removed: get_in(conn, lane, &id)?.is_none(),
            conflicted: main_rev != base_rev,
            id,
            base_rev,
            main_rev,
            lane_rev,
        });
    }
    Ok(out)
}

/// The records that cannot land because main moved under them.
///
/// A CONFLICT IS ONE RECORD, and that is the difference this whole migration buys. It used to be a
/// 27 MB file with markers in it; it is now "lane wrote `x.rs` from main rev 5, main is at rev 7", with
/// base, ours and theirs all three still readable in the ledger.
pub fn lane_conflicts(conn: &Connection, lane: &str) -> Result<Vec<LaneChange>, String> {
    Ok(lane_changes(conn, lane)?.into_iter().filter(|c| c.conflicted).collect())
}

/// What one [`land`] did.
#[derive(Debug, Default, PartialEq, Eq, serde::Serialize)]
pub struct Landed {
    pub applied: usize,
    pub removed: usize,
    pub conflicts: Vec<String>,
}

/// Apply every record in `lane` to `main`, in ONE transaction.
///
/// All or nothing, deliberately: a slice is a unit, and half a slice on main is a state nobody asked
/// for and nobody is watching. If any record conflicts, nothing is applied and the conflicts are
/// named — resolve them in the lane (its base is refreshed by re-reading main), then land again.
///
/// Landing does not delete the lane. Its rows stay in the ledger, so what was landed and from where is
/// still answerable afterwards — the same reason `revert` appends rather than rewinds.
pub fn land(conn: &Connection, lane: &str, by: &str) -> Result<Landed, String> {
    let changes = lane_changes(conn, lane)?;
    let conflicts: Vec<String> = changes.iter().filter(|c| c.conflicted).map(|c| c.id.clone()).collect();
    if !conflicts.is_empty() {
        return Ok(Landed { applied: 0, removed: 0, conflicts });
    }
    let tx = conn.unchecked_transaction().map_err(|e| format!("cannot open a transaction: {e}"))?;
    let mut out = Landed::default();
    for ch in &changes {
        let note = format!("landed from lane '{lane}'");
        match get_in(conn, lane, &ch.id)? {
            Some(body) => {
                put(conn, &ch.id, &body, by, Some(&note), None)?;
                out.applied += 1;
            }
            None => {
                remove(conn, &ch.id, by, Some(&note))?;
                out.removed += 1;
            }
        }
    }
    tx.commit().map_err(|e| format!("cannot commit the landing: {e}"))?;
    Ok(out)
}

/// Re-base `lane` onto main for `id`, taking main's current body as the new base.
///
/// The conflict RESOLUTION primitive, and it is deliberately the smaller half: this says "I have looked
/// at main's version and my lane's version still stands". It does not merge — a three-way merge of two
/// record bodies is a judgement, and the store's job is to make sure both sides are still readable
/// while somebody makes it.
pub fn rebase_record(conn: &Connection, lane: &str, id: &str, by: &str) -> Result<i64, String> {
    let main_rev = head_rev(conn, id)?;
    let body = get_in(conn, lane, id)?
        .ok_or_else(|| format!("lane '{lane}' has no live '{id}' to rebase"))?;
    let head = head_rev_in(conn, lane, id)?;
    let next = head + 1;
    let text = serde_json::to_string(&body).map_err(|e| e.to_string())?;
    conn.execute(
        "INSERT INTO record_revs (id, lane, rev, base_rev, json, tier, at, by, note)
         VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, ?9)",
        params![id, lane, next, main_rev, text, TIER_IMPL, now_ms(), by,
                Some(format!("rebased onto main rev {main_rev}"))],
    )
    .map_err(|e| format!("cannot rebase '{id}' in lane '{lane}': {e}"))?;
    Ok(next)
}

/// Every lane that has ever been written, with how many records it holds.
pub fn lanes(conn: &Connection) -> Result<Vec<(String, i64)>, String> {
    let mut st = conn
        .prepare("SELECT lane, COUNT(DISTINCT id) FROM record_revs GROUP BY lane ORDER BY lane")
        .map_err(|e| e.to_string())?;
    let rows: Vec<(String, i64)> = st
        .query_map([], |r| Ok((r.get(0)?, r.get(1)?)))
        .map_err(|e| e.to_string())?
        .collect::<Result<_, _>>()
        .map_err(|e| e.to_string())?;
    Ok(rows)
}
